   cloze('أكمل قاعدة الرفوف', 'لا تفتح ___ أو شرطًا إلّا وتغلقه قبل أن تفتح غيره، ويبقى للمبتدأ ___ وللشرط ___.', ['صلةً', 'خبر', 'جواب'], ['حالًا', 'فاعل']),
   tf('الجملة الاسمية حالًا تحتاج الواو غالبًا.', 'هند: الجملة الاسمية حالًا تحتاج الواو غالبًا، والجملة الفعلية المضارعة المثبتة لا تأخذ الواو.', 'true', 'خرج وهو يبتسم؛ جاء يحمل.'),
   tf('تمييز العدد ثلاثة إلى عشرة مفرد منصوب.', 'ماريا: أمّا من ثلاثة إلى عشرة فجمع مجرور: ثلاثة صناديق، وهذا درس المستوى الثالث.', 'false', 'جمع مجرور؛ المفرد المنصوب لأحد عشر إلى تسعة وتسعين.'),
   tf('كتبت ماريا جملتها عن فرع الدمّام.', 'هند: ماريا، جملة واحدة فيها الأعمدة الأربعة. عن المنحة. ماريا: الطالبات اللواتي تقدّمن للمنحة هذه السنة ثلاث وعشرون طالبةً.', 'false', 'عن المنحة لا عن الفرع.'),
   tap('المس الحال', ['خرجتُ', 'من', 'المقابلة', 'مطمئنّةً', 'لأنّ', 'الأسئلة', 'واضحة'], 'مطمئنّةً'),
